void conv1d_forward(const int8_t* input, const int8_t* weight,
                    int32_t* output, int in_ch, int out_ch,
                    int length, int kernel, int stride) {
    int out_length = length / stride;
    for (int oc = 0; oc < out_ch; oc++) {
        for (int i = 0; i < out_length; i++) {
            int32_t sum = 0;
            int in_pos = i * stride;
            for (int ic = 0; ic < in_ch; ic++) {
                for (int k = 0; k < kernel; k++) {
                    int input_idx = ic * length + in_pos + k;
                    int weight_idx = oc * in_ch * kernel + ic * kernel + k;
                    sum += input[input_idx] * weight[weight_idx];
                }
            }
            output[oc * out_length + i] = sum;
        }
    }
}

void relu_activation(int32_t* data, int size) {
    for (int i = 0; i < size; i++) {
        if (data[i] < 0) data[i] = 0;
    }
}

void snn_lif_forward(const int8_t* input, int8_t* spike_train,
                     int time_steps, int n_neurons) {
    int8_t membrane[SNN_HIDDEN];
    memset(membrane, 0, sizeof(membrane));
    for (int t = 0; t < time_steps; t++) {
        for (int i = 0; i < n_neurons; i++) {
            int8_t input_val = input[t * SNN_INPUT_SIZE + (i % SNN_INPUT_SIZE)];
            int16_t new_v = membrane[i] + input_val;
            new_v = (new_v * 95) / 100;
            if (new_v > 50) {
                spike_train[t * n_neurons + i] = 127;
                membrane[i] = 0;
            } else {
                spike_train[t * n_neurons + i] = 0;
                membrane[i] = (int8_t)new_v;
            }
        }
    }
}

void lstm_forward(const int8_t* input, const int8_t* w_ih,
                  const int8_t* w_hh, int8_t* hidden,
                  int seq_len, int hidden_size) {
    for (int t = 0; t < seq_len; t++) {
        for (int i = 0; i < hidden_size; i++) {
            int32_t sum = 0;
            for (int j = 0; j < hidden_size; j++) {
                sum += input[t * hidden_size + j] * w_ih[i * hidden_size + j];
                sum += hidden[j] * w_hh[i * hidden_size + j];
            }
            int32_t val = sum >> FIXED_SCALE;
            if (val > 127) val = 127;
            if (val < -128) val = -128;
            hidden[i] = (int8_t)val;
        }
    }
}

void dense_forward(const int8_t* input, const int8_t* weight,
                   const int8_t* bias, int32_t* output,
                   int in_size, int out_size) {
    for (int i = 0; i < out_size; i++) {
        int32_t sum = 0;
        for (int j = 0; j < in_size; j++) {
            sum += input[j] * weight[i * in_size + j];
        }
        sum += bias[i];
        output[i] = sum;
    }
}

int argmax(const int32_t* data, int size) {
    int max_idx = 0;
    int32_t max_val = data[0];
    for (int i = 1; i < size; i++) {
        if (data[i] > max_val) {
            max_val = data[i];
            max_idx = i;
        }
    }
    return max_idx;
}
